SELECT Planification.numcli,Planification.nombrevisite,Planification.T1,Planification.T3,Planification.T2,Planification.T5,Planification.T7,Planification.T4,Planification.T8,Planification.T10,Planification.T12,Planification.T11,Planification.T9,Planification.T6 FROM [Planification] WHERE (((Planification.numcli) In (SELECT [numcli] FROM [Planification] As Tmp GROUP BY [numcli],[nombrevisite] HAVING Count(*)>1  And [nombrevisite] = [Planification].[nombrevisite]))) ORDER BY Planification.numcli
